Translate("zhCN", "rexxar", {
	title = "罗卡鲁",
	subtitle = "部落的勇士",
	found = "游荡在石爪山脉与菲拉斯之间的道路上，途经科多兽坟场",
	hint = "寻找那位身旁伴着一头巨熊、行走在凄凉之地漫长道路上的流浪者。",
	allegiance = "部落",
	sections = {
		{
			title = "概述",
			text = [=[罗卡鲁是一位流浪者和兽王，一名兼有{link:orcs}兽人{/link}与{link:ogres}食人魔{/link}血统的战士，身旁伴着一头名叫米莎的巨熊，行走在{link:kalimdor}卡利姆多{/link}的荒野之中。他不属于任何氏族，也没有家园。然而，当{link:horde}部落{/link}在建立{link:durotar}杜隆塔尔{/link}后陷入最危急的时刻，正是罗卡鲁挺身而出，{link:thrall}萨尔{/link}至今仍将他列为自己的勇士之一。如今他行走在{link:desolace}凄凉之地{/link}的漫长道路上，从{link:stonetalon-mountains}石爪山脉{/link}的边缘一直到{link:feralas}菲拉斯{/link}的森林，想要找到他的人也必须走上这条路。]=],
		},
		{
			title = "意义",
			text = [=[罗卡鲁是年轻{link:horde}部落{/link}的英雄之一。他不打旗帜，也不求回报。他为{link:thrall}萨尔{/link}而战，是因为那是正义的事业，之后他便回到了荒野。他至今仍是大酋长的朋友，并在受召时依然为他效力，这证明了部落对他的信任有多深。]=],
		},
		{
			title = "事迹",
			text = [=[• 在援助{link:horde}部落{/link}之前，他独自流浪了许多年。
• 当海军大将{link:daelin-proudmoore}戴林·普罗德摩尔{/link}率领舰队前来摧毁{link:durotar}杜隆塔尔{/link}时，他与{link:thrall}萨尔{/link}的子民并肩作战，并且是将战火烧向这位海军上将的人之一。
• 当{link:centaurs}半人马{/link}在{link:mulgore}莫高雷{/link}俘虏了{link:cairne-bloodhoof}凯恩·血蹄{/link}之子{link:baine-bloodhoof}贝恩{/link}时，他救出了贝恩。
• 他行走在{link:desolace}凄凉之地{/link}的荒原上，大酋长知道去哪里找他。
• 他找到了一条进入南方黑龙巢穴的道路，并将其提供给大酋长派来的人。]=],
		},
		{
			title = "未载之事",
			text = [=[关于罗卡鲁在对抗海军上将的战争之前的生平，以及是什么驱使他离群独处，编年史中记载甚少。本条目只记录史书和他在{link:desolace}凄凉之地{/link}的事迹所揭示的内容。]=],
		},
	},
	chapters = {
		{
			title = "兽王之战",
			hint = "了解这位响应大酋长召唤的流浪者的故事。",
			text = [=[{link:orcs}兽人{/link}建立新家园之后，{link:kul-tiras}库尔提拉斯{/link}的舰队前来要将他们赶尽杀绝。罗卡鲁几乎是身不由己地卷入了这场战争。他在所到之处召集盟友，有{link:trolls}巨魔{/link}、{link:tauren}牛头人{/link}，也有更奇异的种族，他与他们并肩作战，从{link:durotar}杜隆塔尔{/link}的海岸一直打到{link:theramore-isle}塞拉摩{/link}的{link:swamp-of-sorrows}沼泽{/link}。海军上将倒下之后，罗卡鲁没有留下来领受荣誉。他带着米莎，走回了荒野。]=],
		},
		{
			title = "进入巢穴之路",
			hint = "响应大酋长的召唤，前往凄凉之地寻找他的勇士。",
			text = [=[消息从{link:orgrimmar}奥格瑞玛{/link}传出：大酋长的一位勇士找到了进入一头巨大黑龙巢穴的道路。罗卡鲁研究黑龙军团已久，深知只有其最强大的仆从才能进入，而且必须持有由其将军附魔的钥匙。外人无从得到这样的钥匙，于是罗卡鲁提出了一个骗局。他给{link:lordaeron}洛丹伦{/link}的一位老朋友寄去一封信，那是一位精通幻术的流亡者，而信上一个字也没有写。]=],
		},
		{
			title = "将军之血",
			hint = "将兽王的计划执行到底。",
			text = [=[幻术打开了一扇门，但钥匙需要龙军团将军的鲜血才能唤醒。罗卡鲁没有假装这是一件小事。事成之后，他把完成的护符交到了赢得它的人手中，嘱咐他们为{link:horde}部落{/link}带来胜利。]=],
		},
	},
	mentions = {
		{ text = "{link:horde}部落{/link}的勇士，大酋长的召唤" },
		{ text = "罗卡鲁的遗嘱" },
		{ text = "晋升……" },
		{ text = "黑龙勇士之血" },
	},
	bonds = {
		{ id = "thrall", name = "萨尔", note = "他的大酋长和朋友" },
		{ id = "cairne-bloodhoof", name = "凯恩·血蹄", note = "他所救男孩的父亲" },
		{ id = "daelin-proudmoore", name = "戴林·普罗德摩尔", note = "海军上将之战中的敌人" },
		{ id = "baine-bloodhoof", name = "贝恩·血蹄", note = "从半人马手中救出了他" },
	},
})

